/**
 * Generates lib/quiz-index.ts from the question bank.
 *
 * The bank is 2.2MB once bundled, and every client surface that only wanted a
 * count, a category or a domain was pulling all of it. This emits the metadata
 * those surfaces need, which is a fraction of the size, and leaves the question
 * text, options and explanations to be fetched for the one cert being drilled.
 *
 * Run via `npm run build:index`. tests/content-integrity.test.ts asserts the
 * generated file still matches the bank, so it cannot silently go stale.
 */
import { build } from 'esbuild';
import { writeFileSync, mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

const out = join(mkdtempSync(join(tmpdir(), 'qidx-')), 'bank.mjs');
await build({
  entryPoints: ['lib/playbook-quiz.ts'],
  bundle: true,
  format: 'esm',
  platform: 'node',
  outfile: out,
  logLevel: 'error',
});

const { QUIZ_QUESTIONS } = await import(out);

const entries = QUIZ_QUESTIONS.map((q) => [
  q.id,
  q.certTags,
  q.category,
  q.topic,
  q.difficulty[0], // b | i | a
  q.objectives ?? [],
]);

const file = `/**
 * Generated by scripts/build-quiz-index.mjs. Do not edit by hand.
 *
 * Question metadata without the bodies: enough to count, filter and group by
 * cert, domain, category and difficulty, without shipping 2.2MB of question
 * text to render a number.
 */
import type { QuizDifficulty } from '@/types';

export interface QuizIndexEntry {
  id: string;
  certTags: string[];
  category: string;
  topic: string;
  difficulty: QuizDifficulty;
  objectives: string[];
}

const DIFFICULTY: Record<string, QuizDifficulty> = {
  b: 'beginner',
  i: 'intermediate',
  a: 'advanced',
};

type Row = [string, string[], string, string, string, string[]];

const ROWS: Row[] = ${JSON.stringify(entries)};

export const QUIZ_INDEX: QuizIndexEntry[] = ROWS.map(
  ([id, certTags, category, topic, d, objectives]) => ({
    id,
    certTags,
    category,
    topic,
    difficulty: DIFFICULTY[d],
    objectives,
  }),
);

export const QUIZ_TOTAL = QUIZ_INDEX.length;
`;

writeFileSync('lib/quiz-index.ts', file);
console.log(`wrote lib/quiz-index.ts, ${QUIZ_QUESTIONS.length} entries, ${(file.length / 1024).toFixed(0)}kB`);
